412:                 for (int i = 0; i < bmData.Height; i++)
413:                 {
414:                     for (int j = 0; j < bmData.Width; j++)
415:                     {
416:                         _ImageBaseDataBufferBytes[ImageBaseDataIndex++] = _BitImageBufferBytes[bitmapIndex++];
